describe.each(SHA256_IMPLEMENTATIONS)('with $name', implementation => {
  useSha256Implementation(implementation)

  test.each(CONTENT_LAKE_VARIANT_VERSION_IDS)(
    'matches Content Lake for $scenario: $id',
    async ({variantIds, bundleId, documentId, id}) => {
      expect(
        await createVariantVersionId({
          documentId: PublishedId(documentId),
          variantIds,
          bundleId,
        }),
      ).toBe(id)
      expect(VariantVersionId(id)).toBe(id)
      expect(isVariantVersionIdLike(VariantVersionId(id))).toBe(true)
    },
  )
})
